import torch
import torch.nn as nn


class IrisANN_BN(nn.Module):

    def __init__(self):

        super().__init__()

        self.net = nn.Sequential(

            nn.Linear(4, 16),

            nn.BatchNorm1d(16),

            nn.ReLU(),

            nn.Linear(16, 16),

            nn.BatchNorm1d(16),

            nn.ReLU(),

            nn.Linear(16, 3)
        )

    def forward(self, x):

        return self.net(x)
